using MediatR;using Namaa.Application.Abstractions.Authentication;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.Common.Errors;using Namaa.Application.PurchaseInvoices.Dtos;using Namaa.Domain.Common.Errors;using Namaa.Domain.Common.Results;using Namaa.Domain.Entities;namespace Namaa.Application.PurchaseInvoices.Commands.CreatePurchaseInvoice;public sealed class CreatePurchaseInvoiceCommandHandler(IPurchaseInvoiceRepository repository,IUserRepository users,ICurrentUser currentUser,IApplicationDbContext db):IRequestHandler<CreatePurchaseInvoiceCommand,Result<PurchaseInvoiceDto>>{public async Task<Result<PurchaseInvoiceDto>>Handle(CreatePurchaseInvoiceCommand request,CancellationToken cancellationToken){if(!currentUser.IsAuthenticated||currentUser.UserId is not long actorUserId)return Result.Failure<PurchaseInvoiceDto>(ApplicationErrors.Unauthenticated);if(await repository.ExistsByNumberAsync(request.PurchaseInvoiceNumber,cancellationToken))return Result.Failure<PurchaseInvoiceDto>(PurchaseInvoiceErrors.DuplicateNumber);if(!await users.ExistsByIdAsync(actorUserId,cancellationToken))return Result.Failure<PurchaseInvoiceDto>(new Error("PurchaseInvoices.UserNotFound","The user was not found.",ErrorType.NotFound));var e=PurchaseInvoice.Create(request.SupplierId,request.PurchaseInvoiceNumber,request.IssueDate,actorUserId,request.ProjectId,request.SupplierInvoiceNumber,request.DueDate,request.Notes);await repository.AddAsync(e,cancellationToken);await db.SaveChangesAsync(cancellationToken);return Result.Success(PurchaseInvoiceDto.FromEntity(e));}}
